#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"


void init_exti13(void){
    RCC->AHB1ENR &= ~RCC_AHB1ENR_GPIOCEN; /* Disable GPIOC clock */
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN;  /* Enable GPIOC clock */

    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;  /* Enable GPIOA clock */

    GPIOA->MODER &= ~GPIO_MODER_MODE5; /* Set PA5 as input */
    GPIOA->MODER |= GPIO_MODER_MODE5_0; /* Set PA5 as output */

    GPIOC->MODER &= ~GPIO_MODER_MODE13; /* Set PC13 as input */

    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN; /* Enable SYSCFG clock and EXTI */

    SYSCFG->EXTICR[3] &= ~SYSCFG_EXTICR4_EXTI13; /* Select PC13 for EXTI13 */
    SYSCFG->EXTICR[3] |= SYSCFG_EXTICR4_EXTI13_PC; /* Set EXTI13 to PC13 */

    EXTI->FTSR |= (1 << 13); /* Trigger on falling edge for EXTI13 */
    EXTI->RTSR &=~(1<<13); /* Disable rising edge trigger for EXTI13 */
    EXTI->PR = (1 << 13); 
    EXTI->IMR |= (1 << 13); /* Enable event for EXTI13 */
    
    NVIC_EnableIRQ(EXTI15_10_IRQn); /* Enable EXTI15_10 interrupt in NVIC */
}

int main(void)
{
    init_exti13(); /* Initialize EXTI13 for PC13 */

    while (1)
    {
        /* Main loop code */
    }
}
